solution.code:
#include <stdio.h>

int main() {
    int a[] = {2, 3, 2, 4, 4};
    int result = 0;
    for (int i = 0; i < 5; i++) {
        result ^= a[i];
    }
    printf("%d\n", result);
    return 0;
}
